#[test]
fn class3multi_language_instantiates() {
    let lang = Class3MultiLanguage;
    assert_eq!(lang.name(), "Class3Multi");
}

#[test]
fn class3multi_metadata_populated() {
    let lang = Class3MultiLanguage;
    let meta = lang.metadata();
    assert!(!meta.types().is_empty(), "language should have at least one type");
    assert!(!meta.terms().is_empty(), "language should have at least one term");
}

#[test]
fn unit_class3multi_proc_pzero() {
    let term = Proc::PZero;
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for PZero");
    if let Ok(parsed) = Proc::parse(&displayed) {
        let re_displayed = format!("{}", parsed);
        assert_eq!(
            displayed, re_displayed,
            "Roundtrip failed for PZero: {} != {}",
            displayed, re_displayed
        );
    }
}

#[test]
fn unit_class3multi_name_nquote() {
    mettail_runtime::clear_var_cache();
    let term = Name::NQuote(std::sync::Arc::new(Proc::PZero));
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for NQuote");
    if let Ok(parsed) = Name::parse(&displayed) {
        let re_displayed = format!("{}", parsed);
        assert_eq!(
            displayed, re_displayed,
            "Roundtrip failed for NQuote: {} != {}",
            displayed, re_displayed
        );
    }
}

